<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><h4>Inventory</h4><?php if(session()->getFlashdata('success')):?><div class="alert alert-success"><?=session()->getFlashdata('success')?></div><?php endif;?><?php if(session()->getFlashdata('error')):?><div class="alert alert-danger"><?=esc(session()->getFlashdata('error'))?></div><?php endif;?><table class="table table-sm"><thead><tr><th>Item</th><th>Stock</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=esc($r['name'])?></td><td><?=number_format($r['stock'],3)?></td></tr><?php endforeach;?></tbody></table><div class="card"><div class="card-body"><h6>Stock Adjustment</h6><form method="post" action="<?=site_url('inventory/adjust')?>" class="row g-2"><?=csrf_field()?><div class="col-md-3"><select name="inventory_type" class="form-select"><option value="gas_kg">Gas KG</option><option value="filled_cylinder">Filled cylinder</option><option value="empty_cylinder">Empty cylinder</option></select></div><div class="col-md-3"><select name="cylinder_type_id" class="form-select"><option value="">N/A</option><?php foreach($types as $t):?><option value="<?=$t['id']?>"><?=esc($t['code'].' — '.$t['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select name="direction" class="form-select"><option value="in">IN</option><option value="out">OUT</option></select></div><div class="col-md-2"><input name="quantity" class="form-control" type="number" min=".001" step=".001" placeholder="Qty" required></div><div class="col-md-2"><input name="notes" class="form-control" placeholder="Reason"></div><div class="col-12"><button class="btn btn-primary">Post Adjustment</button></div></form></div></div><?= $this->endSection() ?>